import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		class Fast{
		    StringTokenizer st;
		    String next() throws IOException{
		        while(st==null || !st.hasMoreTokens()){
		            st=new StringTokenizer(br.readLine());
		        }
		        return st.nextToken();
		        
		    }
		    int nextInt() throws IOException{
		        return Integer.parseInt(next());
		        
		    }
		    long nextLong() throws IOException{
		        return Long.parseLong(next());
		        
		    }
		}    
		Fast fs=new Fast();
		StringBuilder t=new StringBuilder();
		int x=fs.nextInt();
		while(x-->0){
		    int n=fs.nextInt();
		    int m=3*n;
		    long[] a=new long[m];
		    for(int i=0;i<m;i++){
		        a[i]=fs.nextLong();
		            
		    }
		    Arrays.sort(a);
		    for(int i=0;i<m/2;i++){
		      long temp=a[i];
		      a[i]=a[m-1-i];
		      a[m-1-i]=temp;
		            
		    }
		    long[] prefix=new long[m+1];
		    for(int i=0;i<m;i++){
		      prefix[i+1]=prefix[i]+a[i];
		            
		    }
		    long ans=Long.MIN_VALUE;
		    for(int i=0;i<=n;i++){
		      int mx=n-i;
		      int l=0,h=mx;
		      while(l<h){
		          int mid=(l+h)/2;
		              int pos=i+2*mid;
		              int lst=3*n-2*i-mid-1;
		              long change=a[pos]+a[pos+1]-3L*a[lst];
		              if(change>0) l=mid+1;
		              else h=mid;
		      }
            
              int j=l;
              int se=i+2*j;
              int te=3*n-2*i-j;
              long sc=6L*prefix[i]+4L*(prefix[se]-prefix[i])+3L*(prefix[te]-prefix[se]);
              ans=Math.max(ans,sc);
		        
		    }
		    t.append(ans).append('\n');
		}    
		System.out.print(t);
	
		    
		    
	}    
	
		
			
	
}
